"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type EasingPrimitiveProps = ComponentProps<typeof motion.div>;

export function EasingPrimitive({ children, ...props }: EasingPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {x: -120}}
      animate={{x: 120}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.52, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
